const ar = (x1, y1, x2, y2, c = "k") => { const a = Math.atan2(y2 - y1, x2 - x1), L = 8, w = 4; const bx = x2 - L * Math.cos(a), by = y2 - L * Math.sin(a); const px = -Math.sin(a) * w, py = Math.cos(a) * w; return `<line class="v${c}" x1="${x1}" y1="${y1}" x2="${bx.toFixed(1)}" y2="${by.toFixed(1)}"/><polygon class="h${c}" points="${x2},${y2} ${(bx + px).toFixed(1)},${(by + py).toFixed(1)} ${(bx - px).toFixed(1)},${(by - py).toFixed(1)}"/>`; };
